// @pit: {"label": "Commit, push, and open the PR for the collapsed thread footer"}
async ({ git: { add, commit, push }, shell: { execFile } }) => {
  await add(["src/formatting.ts", "src/formatting.test.ts", "src/run.ts", "src/run.test.ts", "docs/how-it-works.md", "docs/threads.md"]);
  const c = await commit(["-m", "feat: show how to read the thread in a collapsed comment footer", "-m", "The footer of each comment was a terse `🧵 Thread state: <ref>` line. It is\nnow a collapsed section, `🧵 This conversation is stored in git on <ref>`,\nwith the git commands that read the thread, which the job summary had. The\njob summary keeps them only in output mode, where pi-action posts no comment.", "-m", "Refs #80"]);
  await push(["-u", "origin", "feat/80-thread-state-details"]);
  const pr = await execFile("gh", ["pr", "create", "--base", "main", "--head", "feat/80-thread-state-details",
    "--title", "feat: show how to read the thread in a collapsed comment footer",
    "--body", `Refs #80 ([comment](https://github.com/cv/pi-action/issues/80#issuecomment-6872489664)).

The footer of each pi-action comment was \`🧵 Thread state: refs/pi/threads/80 (git fetch origin refs/pi/threads/80)\`. Now it's a collapsed section with the commands from the job summary:

<details><summary><sub>🧵 This conversation is stored in git on <code>refs/pi/threads/80</code></sub></summary>

Read it from a clone of this repository ([more](https://github.com/cv/pi-action/blob/main/docs/threads.md#read-a-thread)):

\`\`\`bash
git fetch origin 'refs/pi/threads/80:refs/pi/threads/80'
git log --oneline refs/pi/threads/80            # one commit for each stored step
git show refs/pi/threads/80:batch.json | jq .   # the records of the newest step
\`\`\`

</details>

- \`<sub>\` is inside \`<summary>\`: GitHub drops a \`<sub>\` that wraps the whole \`<details>\` (checked with the Markdown API).
- The job summary keeps the commands only in \`output\` mode, where pi-action posts no comment. The workflow log still shows them in the \`🧵 Thread\` group.
- Docs: \`docs/how-it-works.md\` (step 9) and \`docs/threads.md\` (Read a thread).

\`npm run check\` passes.`], { raise: true });
  return [c.stdout.split("\n")[0], pr.stdout.trim()];
}
